//! Committed-gencode authentication and drift guard.
//!
//! `sim/trace/src/pb/dynamic_trace.rs` is COMMITTED and generated by
//! `sim/trace/regen_pb.sh` with pinned protoc/prost inputs. The SHA-256 below
//! authenticates its exact bytes during every Rust test. Schema pins catch any
//! changed or newly added `.proto`; `regen_pb.sh --check` independently generates
//! outside the repository and diffs the result without modifying tracked bytes.
//!
//! On intentional schema changes: run `sim/trace/regen_pb.sh --write`, commit the
//! regenerated `dynamic_trace.rs`, and update both pin sets below in the SAME
//! commit (multi-surface lockstep rule).

use std::path::PathBuf;

use sim_trace::Sha256Digest;

const GENERATED_BINDING_SHA256: &str =
    "ce69ab506bf01e89f1ab3acd08b3a540031857b539c2d1e3173ab56aa7888227";

const PROTO_PINS: &[(&str, u64)] = &[
    ("address.proto", 0xb768cd17c42a1788),
    ("cuda_stream.proto", 0xad1565c52bd75656),
    ("dim3d.proto", 0x13d2f3d8144e1420),
    ("gpu_device.proto", 0x456a3472a1018842),
    ("instruction.proto", 0xa387ffa3c65bcb44),
    ("kernel.proto", 0x3adc739e21faa22b),
    ("threadblock.proto", 0x0424145b630ec29a),
    ("trace.proto", 0xc7577e6647181017),
    ("warp.proto", 0xf6568d1a9c8bdf7b),
];

fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

fn proto_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tools/nvbit_tracer/traces_enhanced/dynamic_trace")
        .canonicalize()
        .expect("proto schema dir exists in-repo")
}

fn binding_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("src/pb/dynamic_trace.rs")
        .canonicalize()
        .expect("committed Rust binding exists in-repo")
}

#[test]
fn committed_binding_bytes_match_sha256_pin() {
    let path = binding_path();
    let raw = std::fs::read(&path).expect("read committed Rust binding");
    assert_eq!(
        Sha256Digest::of(&raw).to_string(),
        GENERATED_BINDING_SHA256,
        "committed Prost binding bytes changed without pinned external regeneration; run \
         sim/trace/regen_pb.sh --check, and use --write plus a pin update only for an \
         intentional schema change"
    );
}

#[test]
fn committed_gencode_matches_proto_schema() {
    let dir = proto_dir();
    let mut mismatches = Vec::new();
    for (name, pin) in PROTO_PINS {
        let bytes = std::fs::read(dir.join(name))
            .unwrap_or_else(|e| panic!("{name}: {e} — .proto removed without updating the pins?"));
        let got = fnv1a64(&bytes);
        if got != *pin {
            mismatches.push(format!("{name}: pinned {pin:#018x}, on-disk {got:#018x}"));
        }
    }
    assert!(
        mismatches.is_empty(),
        ".proto schema changed without regenerating the committed Rust bindings.\n\
         Run sim/trace/regen_pb.sh --write, commit dynamic_trace.rs, and update \
         PROTO_PINS plus GENERATED_BINDING_SHA256 in the SAME commit:\n{}",
        mismatches.join("\n")
    );
}

/// A NEW .proto added upstream must also be added to the pins (and to the
/// generated bindings) — enumeration catches silent omission.
#[test]
fn no_unpinned_proto_files() {
    let dir = proto_dir();
    let mut on_disk: Vec<String> = std::fs::read_dir(&dir)
        .expect("read proto dir")
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .filter(|n| n.ends_with(".proto"))
        .collect();
    on_disk.sort();
    let mut pinned: Vec<String> = PROTO_PINS.iter().map(|(n, _)| n.to_string()).collect();
    pinned.sort();
    assert_eq!(
        on_disk, pinned,
        "proto files on disk diverge from PROTO_PINS — regen + repin in the same commit"
    );
}
